    o.userData.efMovementBarriers=spans.map(([a,b])=>({label:'Concertina wire',x:(a+b)/2,y:1.2,z:0,hx:(b-a)/2,hy:1.29,hz:1.29,ry:0}));
    for(let i=0;i<9;i++) {
      if(!spans.some(([a,b])=>-8+i*2>=a+.15&&-8+i*2<=b-.15))continue;
      const ring=mesh(o,geometries.torus,'rust',-8+i*2,1.2,0,1.15,1.15,1.15);ring.rotation.y=Math.PI/2;
    }
    for(const [a,b]of spans)for(const xx of [a===-9.3?-9:a+.1,b===9.3?9:b-.1])beam(o,'steel',[xx,0,0],[xx,2.4,0],.14);
    add(g,o,x,z,ry);
