  function facade(g,x,z,w,h,d,{destroyed=false,m='concrete',floors=2,doorWidth=0}={}) {
    // Columns and floor beams leave real open apertures rather than painting windows.
    pad(g,x,z,w+.6,d+.6,'edge');
    for(let f=0;f<floors;f++){
      const fy=f*h/floors;
      box(g,'edge',x,fy+.2,z,w,.4,d);
      for(const zz of [z-d/2,z+d/2]){
        const entrance=f===0&&zz===z+d/2&&doorWidth>0;
        if(entrance){
          const sideWidth=(w-doorWidth)/2;
          for(const side of [-1,1])box(g,m,x+side*(doorWidth+sideWidth)/2,fy+.9,zz,sideWidth,1.4,.65);
        }else box(g,m,x,fy+.9,zz,w,1.4,.65);
        if(!destroyed||f<floors-1)box(g,m,x,fy+h/floors-.55,zz,w,1.1,.65);
        const n=Math.max(3,Math.round(w/5));
        for(let i=0;i<=n;i++){
          if(destroyed&&f===floors-1&&(i===2||i===n-1))continue;
          if(entrance&&Math.abs(-w/2+i*w/n)<doorWidth/2+.375)continue;
          box(g,m,x-w/2+i*w/n,fy+h/floors*.52,zz,.75,h/floors,.7);
        }
      }
      for(const xx of [x-w/2,x+w/2]){
        box(g,m,xx,fy+.9,z,.7,1.4,d);
        if(!destroyed||f<floors-1)box(g,m,xx,fy+h/floors-.55,z,.7,1.1,d);
        const n=Math.max(2,Math.round(d/5));
        for(let i=0;i<=n;i++)box(g,m,xx,fy+h/floors*.52,z-d/2+i*d/n,.7,h/floors,.75);
      }
    }
    if(!destroyed)roof(box(g,'steel',x,h+.25,z,w+1,.6,d+1));
    else{
      for(let zz=z-d/2;zz<=z+d/2;zz+=d/3){beam(g,'rust',[x-w/2,h,zz],[x,h+3,zz],.35);beam(g,'rust',[x,h+3,zz],[x+w/2,h,zz],.35);}
      const r=rng(Math.round(x*37+z*14+4000));
      for(let i=0;i<20;i++){const xx=x+(r()-.5)*(w+8),zz=z+(r()-.5)*(d+8);const o=box(g,i%3?'rubble':'brick',xx,.3+r()*.7,zz,.7+r()*2,.5+r()*1.2,.8+r()*2.5,r()*Math.PI);o.rotation.x=r()*.4;}
    }
  }
