    box(roofGroup,'dark',pill?-5:-4,roofY+.35,2,1.3,.7,1.3,true);for(const z of [1.6,2,2.4])box(roofGroup,'steel',pill?-5:-4,roofY+.73,z,1.45,.1,.08);
