  box(yaw,'timber',-.88,-.07,.86,.56,.09,.55);
  box(yaw,'steelDark',-.88,-.28,.86,.06,.38,.06);
  model.userData.efDesignRevision='battlefield-design-20261122-v1';
  model.userData.efSurfaceRevision='battlefield-vehicles-20261123-v2';
